-- Zangarmarsh: creature abilities
-- Most of the zone's creatures (the Bogstrok, the naga, the Ango'rosh ogres, the sporebats, fungal giants and marsh wildlife) had
-- no AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows
-- needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The
-- creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '17855,17877,18046,18088,18113,18122,18130,18131,18201,18212,18214,18285,18340,18680,18681,18682,19349,19706,19729,19730,20090,20196,20279,20280,20283,20290,20291,20293,20442,21894';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '18909,18910,18912,18922,18943,18992,19734,51878,51880';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
